describe('listing sessions over the message handler', () => {
  it('queries listFor with the session userId, serialises dates to ISO strings, answers empty without listFor, and logs a ws error when listFor throws', async () => {
    const orchestrator = {processMessageStream: jest.fn()} as unknown as ChatOrchestrator;
    const session: ChatSession = {sessionId: 's1', userId: 'u-auth', entries: []};
    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const asked: Array<{userId: string | number; limit?: number; before?: unknown}> = [];
    const storeWithList = {
      listFor: async (userId: string | number, options?: {limit?: number; before?: unknown}) => {
        asked.push({userId, limit: options?.limit, before: options?.before});
        return [
          {
            sessionId: 's9',
            createdAt: new Date('2026-02-01T10:00:00.000Z'),
            updatedAt: new Date('2026-02-01T10:05:00.000Z'),
            entryCount: 3,
          },
        ];
      },
    } as unknown as SessionStore;
    const throwingStore = {
      listFor: async () => {
        throw new Error('store unavailable');
      },
    } as unknown as SessionStore;
    const wsErrors: Array<{category: string; fields?: Record<string, unknown>}> = [];
    const noop = () => undefined;
    setLogger({
      debug: noop,
      info: noop,
      warn: noop,
      error: (category, _message, fields) => void wsErrors.push({category, fields}),
    });

    try {
      const before = {updatedAt: '2026-02-01T12:00:00.000Z', sessionId: 's10'};
      await createMessageHandler(orchestrator, storeWithList)(ws, session, {
        type: 'list_sessions',
        limit: 5,
        before,
      });
      await createMessageHandler(orchestrator)(ws, session, {type: 'list_sessions'});
      await createMessageHandler(orchestrator, throwingStore)(ws, session, {type: 'list_sessions'});
    } finally {
      setLogger();
    }

    expect({asked, sent, wsErrors}).toEqual({
      asked: [{userId: 'u-auth', limit: 5, before}],
      sent: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's9',
              createdAt: '2026-02-01T10:00:00.000Z',
              updatedAt: '2026-02-01T10:05:00.000Z',
              entryCount: 3,
            },
          ],
        },
        {type: 'session_list', sessions: []},
        {type: 'error', code: 'SERVER_ERROR', message: expect.any(String)},
      ],
      wsErrors: [{category: 'ws', fields: expect.objectContaining({userId: 'u-auth', error: 'store unavailable'})}],
    });
  });
});

